     1	package com.loja.orderservice.integration;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import lombok.RequiredArgsConstructor;
     5	import org.springframework.beans.factory.annotation.Value;
     6	import org.springframework.stereotype.Service;
     7	import java.io.IOException;
     8	import java.net.URI;
     9	import java.net.http.HttpClient;
    10	import java.net.http.HttpRequest;
    11	import java.net.http.HttpResponse;
    12	import java.time.Duration;
    13	import java.util.Map;
    14	import java.util.Optional;
    15	
    16	@Service
    17	@RequiredArgsConstructor
    18	public class TransLogClient {
    19	    @Value("${translog.url:http://localhost:8081}")
    20	    private String translogUrl;
    21	
    22	    private final ObjectMapper objectMapper;
    23	
    24	    public Optional<TransLogQuoteResponse> getQuote(String zipCode, Integer weightGrams, String service) {
    25	        try {
    26	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    27	                    translogUrl, zipCode, weightGrams, service);
    28	
    29	            HttpClient httpClient = HttpClient.newBuilder()
    30	                    .connectTimeout(Duration.ofSeconds(2))
    31	                    .build();
    32	
    33	            HttpRequest request = HttpRequest.newBuilder()
    34	                    .uri(URI.create(url))
    35	                    .timeout(Duration.ofSeconds(2))
    36	                    .GET()
    37	                    .build();
    38	
    39	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    40	
    41	            if (response.statusCode() == 200) {
    42	                @SuppressWarnings("unchecked")
    43	                Map<String, Object> responseBody = objectMapper.readValue(response.body(), Map.class);
    44	
    45	                if (responseBody.containsKey("error")) {
    46	                    if ("ZIP_NOT_SERVED".equals(responseBody.get("error"))) {
    47	                        return Optional.empty();
    48	                    }
    49	                    return Optional.empty();
    50	                }
    51	
    52	                Integer priceCents = ((Number) responseBody.get("price_cents")).intValue();
    53	                Integer etaHours = ((Number) responseBody.get("eta_hours")).intValue();
    54	
    55	                return Optional.of(TransLogQuoteResponse.builder()
    56	                        .priceCents(priceCents)
    57	                        .etaHours(etaHours)
    58	                        .build());
    59	            }
    60	
    61	            return Optional.empty();
    62	        } catch (IOException | InterruptedException e) {
    63	            return Optional.empty();
    64	        }
    65	    }
    66	
    67	    @lombok.Data
    68	    @lombok.NoArgsConstructor
    69	    @lombok.AllArgsConstructor
    70	    @lombok.Builder
    71	    public static class TransLogQuoteResponse {
    72	        private Integer priceCents;
    73	        private Integer etaHours;
    74	    }
    75	}
